cssCode:
.scroll-burst-wrap { height: 250vh; width: 100%; position: relative; }
.sticky-center {
  position: sticky; top: 0; height: 100vh; width: 100%;
  display: flex; align-items: center; justify-content: center; overflow: hidden;
}
.aura-bg {
  position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%);
  width: 0px; height: 0px; border-radius: 50%;
  background: radial-gradient(circle, rgba(168,85,247,0.8) 0%, transparent 70%);
  filter: blur(40px); transition: width 0.1s linear, height 0.1s linear;
}
.crystal {
  position: relative; width: 100px; height: 100px;
  background: linear-gradient(135deg, rgba(255,255,255,0.1), rgba(255,255,255,0));
  backdrop-filter: blur(10px); border: 1px solid rgba(168,85,247,0.5);
  box-shadow: 0 0 30px rgba(124, 58, 237, 0.4);
  transition: transform 0.1s linear, border-radius 0.1s linear;
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;overflow-y:auto;background:transparent;';

const wrap = document.createElement('div');
wrap.className = 'scroll-burst-wrap';

const sticky = document.createElement('div');
sticky.className = 'sticky-center';

const aura = document.createElement('div');
aura.className = 'aura-bg';

const crystal = document.createElement('div');
crystal.className = 'crystal';

sticky.appendChild(aura);
sticky.appendChild(crystal);
wrap.appendChild(sticky);
c.appendChild(wrap);

c.addEventListener('scroll', () => {
  const scrolled = c.scrollTop;
  // ઑબ્જેક્ટને ફેરવવું અને મોટું કરવું
  crystal.style.transform = `rotate(${45 + scrolled * 0.3}deg) scale(${1 + scrolled * 0.005})`;
  crystal.style.borderRadius = `${Math.min(50, scrolled * 0.1)}%`;
  // પાછળનો પ્રકાશ ફેલાવવો
  aura.style.width = `${scrolled * 1.5}px`;
  aura.style.height = `${scrolled * 1.5}px`;
});
